    /**
     * Test case where the function values at endpoints have the same sign.
     * This covers the IllegalArgumentException branch (sign >= 0).
     */
    @Test(expected = IllegalArgumentException.class)
    public void testSolve_NoBracketing_SameSign() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x^2 + 1, always positive, no root
        UnivariateRealFunction f = x -> x * x + 1.0;
        BrentSolver solver = new BrentSolver(f);

        double min = -1.0;
        double max = 1.0;
        // This should throw IllegalArgumentException because yMin * yMax > 0
        solver.solve(min, max);
    }








