import static org.junit.Assert.*;

/**
 * Unit tests for BrentSolver.solve(double, double)
 * Aiming for maximum branch and line coverage.
 */
public class BrentSolver_solve_TriageGen2Test {











    /**
     * Test case where max iterations are exceeded.
     * This covers the potential throwing of MaxIterationsExceededException.
     */
    @Test(expected = MaxIterationsExceededException.class)
    public void testSolve_MaxIterationsExceeded() throws MaxIterationsExceededException, FunctionEvaluationException {
        // A function that converges extremely slowly or is designed to fail Brent's criteria
        // In a real scenario, we'd mock the function or use a specific complex function.
        // For this test, we use a function that behaves poorly for the solver.
        UnivariateRealFunction f = new UnivariateRealFunction() {
            private int count = 0;
            @Override
            public double value(double x) {
                count++;
                // Force convergence issues if we could control the internal solver state,
                // but here we simulate a scenario where the solver would exhaust attempts.
                // Since we cannot easily inject max iterations into the BrentSolver constructor 
                // via the provided signature, we assume standard behavior.
                return Math.sin(x); 
            }
        };

        // Note: To truly trigger MaxIterationsExceeded with the standard BrentSolver, 
        // one usually needs a very narrow tolerance or a pathological function.
        // This is a placeholder for the logic path.
        BrentSolver solver = new BrentSolver(x -> {
            // A function that oscillates wildly to prevent convergence
            return Math.sin(1.0 / x);
        });

        // Attempting to solve near zero where oscillation is infinite
        solver.solve(0.000000001, 1.0);
    }
}
